-- POPS-4356: persisted catalogue revision one. The snapshot is atomic because
-- drizzle runs each journal entry in one SQLite transaction.
PRAGMA defer_foreign_keys = ON;--> statement-breakpoint
CREATE TABLE `catalogue_revisions` (`revision` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `base_revision` integer REFERENCES `catalogue_revisions`(`revision`), `status` text NOT NULL, `minimum_protocol` integer NOT NULL, `created_actor_kind` text NOT NULL, `created_actor_id` text, `created_actor_label` text, `created_at` text NOT NULL, `published_actor_kind` text, `published_actor_id` text, `published_actor_label` text, `published_at` text, `publication_note` text, `abandoned_actor_kind` text, `abandoned_actor_id` text, `abandoned_actor_label` text, `abandoned_at` text, CONSTRAINT `ck_catalogue_revisions_status` CHECK(`status` IN ('draft', 'published', 'abandoned')), CONSTRAINT `ck_catalogue_revisions_minimum_protocol` CHECK(`minimum_protocol` >= 1), CONSTRAINT `ck_catalogue_revisions_terminal_state` CHECK((`status` = 'draft' AND `published_at` IS NULL AND `abandoned_at` IS NULL) OR (`status` = 'published' AND `published_at` IS NOT NULL AND `abandoned_at` IS NULL) OR (`status` = 'abandoned' AND `published_at` IS NULL AND `abandoned_at` IS NOT NULL)));--> statement-breakpoint
CREATE UNIQUE INDEX `catalogue_revisions_one_draft` ON `catalogue_revisions` (`status`) WHERE `status` = 'draft';--> statement-breakpoint
CREATE TABLE `item_types` (`revision` integer NOT NULL REFERENCES `catalogue_revisions`(`revision`), `id` text NOT NULL, `key` text NOT NULL, `label` text NOT NULL, `description` text, `sort_order` integer NOT NULL, `capabilities_json` text NOT NULL, `legacy_labels_json` text NOT NULL, `presentation_json` text NOT NULL, `archived_at` text, PRIMARY KEY (`revision`, `id`), CONSTRAINT `ck_item_types_sort_order` CHECK(`sort_order` >= 0), CONSTRAINT `ck_item_types_capabilities_json` CHECK(json_valid(`capabilities_json`) AND json_type(`capabilities_json`) = 'array'), CONSTRAINT `ck_item_types_legacy_labels_json` CHECK(json_valid(`legacy_labels_json`) AND json_type(`legacy_labels_json`) = 'array'), CONSTRAINT `ck_item_types_presentation_json` CHECK(json_valid(`presentation_json`) AND json_type(`presentation_json`) = 'object'));--> statement-breakpoint
CREATE UNIQUE INDEX `item_types_revision_key` ON `item_types` (`revision`, `key` COLLATE NOCASE);--> statement-breakpoint
CREATE TABLE `item_type_fields` (`revision` integer NOT NULL, `id` text NOT NULL, `type_id` text NOT NULL, `key` text NOT NULL, `label` text NOT NULL, `help` text, `sort_order` integer NOT NULL, `kind` text NOT NULL, `cardinality` text NOT NULL, `required` integer NOT NULL, `storage` text NOT NULL, `fixed_unit` text, `reference_kinds_json` text NOT NULL, `reference_type_ids_json` text NOT NULL, `expression_version` integer, `expression_json` text, `allow_override` integer NOT NULL, `presentation_json` text NOT NULL, `archived_at` text, PRIMARY KEY (`revision`, `id`), FOREIGN KEY (`revision`, `type_id`) REFERENCES `item_types`(`revision`, `id`), CONSTRAINT `ck_item_type_fields_kind` CHECK(`kind` IN ('short_text','long_text','integer','decimal','boolean','enum','measurement','date','date_time','url','reference')), CONSTRAINT `ck_item_type_fields_sort_order` CHECK(`sort_order` >= 0), CONSTRAINT `ck_item_type_fields_cardinality` CHECK(`cardinality` IN ('one', 'many')), CONSTRAINT `ck_item_type_fields_boolean_cardinality` CHECK(`kind` <> 'boolean' OR `cardinality` = 'one'), CONSTRAINT `ck_item_type_fields_required` CHECK(`required` IN (0, 1)), CONSTRAINT `ck_item_type_fields_storage` CHECK(`storage` IN ('stored', 'computed')), CONSTRAINT `ck_item_type_fields_allow_override` CHECK(`allow_override` IN (0, 1)), CONSTRAINT `ck_item_type_fields_reference_kinds_json` CHECK(json_valid(`reference_kinds_json`) AND json_type(`reference_kinds_json`) = 'array'), CONSTRAINT `ck_item_type_fields_reference_type_ids_json` CHECK(json_valid(`reference_type_ids_json`) AND json_type(`reference_type_ids_json`) = 'array'), CONSTRAINT `ck_item_type_fields_presentation_json` CHECK(json_valid(`presentation_json`) AND json_type(`presentation_json`) = 'object'), CONSTRAINT `ck_item_type_fields_expression_json` CHECK(`expression_json` IS NULL OR json_valid(`expression_json`)), CONSTRAINT `ck_item_type_fields_storage_shape` CHECK((`storage` = 'stored' AND `expression_version` IS NULL AND `expression_json` IS NULL AND `allow_override` = 0) OR (`storage` = 'computed' AND `expression_version` IS NOT NULL AND `expression_json` IS NOT NULL)));--> statement-breakpoint
CREATE UNIQUE INDEX `item_type_fields_revision_type_key` ON `item_type_fields` (`revision`, `type_id`, `key` COLLATE NOCASE);--> statement-breakpoint
CREATE TABLE `field_enum_options` (`revision` integer NOT NULL, `id` text NOT NULL, `field_id` text NOT NULL, `key` text NOT NULL, `label` text NOT NULL, `sort_order` integer NOT NULL, `archived_at` text, PRIMARY KEY (`revision`, `id`), FOREIGN KEY (`revision`, `field_id`) REFERENCES `item_type_fields`(`revision`, `id`), CONSTRAINT `ck_field_enum_options_sort_order` CHECK(`sort_order` >= 0));--> statement-breakpoint
CREATE UNIQUE INDEX `field_enum_options_revision_field_key` ON `field_enum_options` (`revision`, `field_id`, `key` COLLATE NOCASE);--> statement-breakpoint
CREATE TABLE `catalogue_compatibility` (`from_revision` integer NOT NULL REFERENCES `catalogue_revisions`(`revision`), `to_revision` integer NOT NULL REFERENCES `catalogue_revisions`(`revision`), `classification` text NOT NULL, `affected_ids_json` text NOT NULL, `migration_name` text, PRIMARY KEY (`from_revision`, `to_revision`), CONSTRAINT `ck_catalogue_compatibility_affected_ids_json` CHECK(json_valid(`affected_ids_json`) AND json_type(`affected_ids_json`) = 'array'), CONSTRAINT `ck_catalogue_compatibility_order` CHECK(`from_revision` < `to_revision`));--> statement-breakpoint
CREATE TABLE `catalogue_events` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `revision` integer NOT NULL REFERENCES `catalogue_revisions`(`revision`), `kind` text NOT NULL, `actor_kind` text NOT NULL, `actor_id` text, `actor_label` text, `before_json` text NOT NULL, `after_json` text NOT NULL, `migration_name` text, `affected_items` integer DEFAULT 0 NOT NULL, `server_time` text NOT NULL, CONSTRAINT `ck_catalogue_events_before_json` CHECK(json_valid(`before_json`) AND json_type(`before_json`) = 'object'), CONSTRAINT `ck_catalogue_events_after_json` CHECK(json_valid(`after_json`) AND json_type(`after_json`) = 'object'), CONSTRAINT `ck_catalogue_events_affected_items` CHECK(`affected_items` >= 0));--> statement-breakpoint
CREATE INDEX `catalogue_events_revision` ON `catalogue_events` (`revision`, `id`);--> statement-breakpoint
CREATE TABLE `migration_0017_catalogue_seed` (`catalogue_json` text NOT NULL CHECK(json_valid(`catalogue_json`)));--> statement-breakpoint
