INSERT INTO `catalogue_revisions` (`revision`,`status`,`minimum_protocol`,`created_actor_kind`,`created_actor_id`,`created_actor_label`,`created_at`,`published_actor_kind`,`published_actor_id`,`published_actor_label`,`published_at`,`publication_note`) VALUES (1,'published',1,'migration','0017_persisted_item_types','Migration',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration','0017_persisted_item_types','Migration',strftime('%Y-%m-%dT%H:%M:%fZ','now'),'Initial persisted catalogue');--> statement-breakpoint
INSERT INTO `item_types` (`revision`,`id`,`key`,`label`,`sort_order`,`capabilities_json`,`legacy_labels_json`,`presentation_json`) SELECT 1,json_extract(t.value,'$.id'),json_extract(t.value,'$.key'),json_extract(t.value,'$.label'),json_extract(t.value,'$.sortOrder'),json_extract(t.value,'$.capabilities'),json_extract(t.value,'$.legacyLabels'),json_extract(t.value,'$.presentation') FROM `migration_0017_catalogue_seed` s,json_each(s.`catalogue_json`) t;--> statement-breakpoint
INSERT INTO `item_type_fields` (`revision`,`id`,`type_id`,`key`,`label`,`help`,`sort_order`,`kind`,`cardinality`,`required`,`storage`,`fixed_unit`,`reference_kinds_json`,`reference_type_ids_json`,`allow_override`,`presentation_json`) SELECT 1,json_extract(f.value,'$.id'),json_extract(t.value,'$.id'),json_extract(f.value,'$.key'),json_extract(f.value,'$.label'),json_extract(f.value,'$.help'),json_extract(f.value,'$.sortOrder'),json_extract(f.value,'$.kind'),'one',0,'stored',json_extract(f.value,'$.fixedUnit'),'[]','[]',0,json_extract(f.value,'$.presentation') FROM `migration_0017_catalogue_seed` s,json_each(s.`catalogue_json`) t,json_each(t.value,'$.fields') f;--> statement-breakpoint
INSERT INTO `field_enum_options` (`revision`,`id`,`field_id`,`key`,`label`,`sort_order`) SELECT 1,json_extract(o.value,'$.id'),json_extract(f.value,'$.id'),json_extract(o.value,'$.key'),json_extract(o.value,'$.label'),json_extract(o.value,'$.sortOrder') FROM `migration_0017_catalogue_seed` s,json_each(s.`catalogue_json`) t,json_each(t.value,'$.fields') f,json_each(f.value,'$.options') o;--> statement-breakpoint
CREATE TABLE `migration_0017_abort` (`must_be_zero` integer NOT NULL CHECK(`must_be_zero` = 0));--> statement-breakpoint
INSERT INTO `migration_0017_abort` SELECT 1 FROM `migration_0017_catalogue_seed` WHERE inventory_catalogue_seed_parity(`catalogue_json`) <> 1;--> statement-breakpoint
INSERT INTO `migration_0017_abort` SELECT 1 WHERE EXISTS (SELECT 1 FROM `items` i WHERE i.`type_key` IS NOT NULL AND NOT EXISTS (SELECT 1 FROM `item_types` t WHERE t.`revision` = 1 AND t.`key` = i.`type_key` COLLATE NOCASE));--> statement-breakpoint
INSERT INTO `migration_0017_abort` SELECT 1 WHERE EXISTS (SELECT 1 FROM `items` i WHERE i.`type_key` IS NULL AND i.`fields` <> '{}');--> statement-breakpoint
INSERT INTO `migration_0017_abort` SELECT 1 WHERE EXISTS (SELECT 1 FROM `items` i,json_each(i.`fields`) v WHERE NOT (i.`type_key` = 'bulb' AND v.`key` = 'Colour temperature') AND NOT EXISTS (SELECT 1 FROM `item_types` t JOIN `item_type_fields` f ON f.`revision` = t.`revision` AND f.`type_id` = t.`id` WHERE t.`revision` = 1 AND t.`key` = i.`type_key` COLLATE NOCASE AND f.`key` = v.`key` COLLATE NOCASE));--> statement-breakpoint
