CREATE TABLE `items` (`id` text PRIMARY KEY NOT NULL, `name` text NOT NULL, `type_id` text, `note` text, `code` text, `external_ids` text DEFAULT '[]' NOT NULL, `quantity` integer DEFAULT 1 NOT NULL, `lifecycle` text DEFAULT 'active' NOT NULL, `lifecycle_changed_at` text, `placement_kind` text NOT NULL, `location_id` text REFERENCES `locations`(`id`), `containing_item_id` text REFERENCES `items`(`id`), `previous_placement_kind` text, `previous_location_id` text, `previous_containing_item_id` text, `is_container` integer DEFAULT 0 NOT NULL, `access` text, `is_full` integer, `legacy_type` text, `location_text` text, `room` text, `item_id` text, `brand` text, `model` text, `condition` text DEFAULT 'Good', `in_use` integer, `deductible` integer, `purchase_date` text, `warranty_expires` text, `replacement_value` real, `resale_value` real, `purchase_transaction_id` text, `purchase_transaction_uri` text, `purchase_transaction_stale_at` text, `purchased_from_id` text, `purchased_from_name` text, `purchase_price` real, `owner_uri` text, `owner_stale_at` text, `source_ref` text, `notion_id` text, `last_edited_time` text NOT NULL, `revision` integer DEFAULT 1 NOT NULL, `seq` integer NOT NULL, `created_at` text DEFAULT (datetime('now')) NOT NULL, `updated_at` text DEFAULT (datetime('now')) NOT NULL, `deleted_at` text, CONSTRAINT `ck_items_placement` CHECK((`placement_kind` = 'location' AND `location_id` IS NOT NULL AND `containing_item_id` IS NULL) OR (`placement_kind` = 'container' AND `containing_item_id` IS NOT NULL AND `location_id` IS NULL) OR (`placement_kind` = 'hand' AND `location_id` IS NULL AND `containing_item_id` IS NULL)), CONSTRAINT `ck_items_previous_placement` CHECK((`previous_placement_kind` IS NULL AND `previous_location_id` IS NULL AND `previous_containing_item_id` IS NULL) OR (`placement_kind` = 'hand' AND ((`previous_placement_kind` IS 'location' AND `previous_location_id` IS NOT NULL AND `previous_containing_item_id` IS NULL) OR (`previous_placement_kind` IS 'container' AND `previous_containing_item_id` IS NOT NULL AND `previous_location_id` IS NULL)))), CONSTRAINT `ck_items_not_self_contained` CHECK(`containing_item_id` <> `id`), CONSTRAINT `ck_items_quantity` CHECK(`quantity` >= 1), CONSTRAINT `ck_items_lifecycle` CHECK(`lifecycle` IN ('active','retired','discarded','lost','destroyed')), CONSTRAINT `ck_items_is_container` CHECK(`is_container` IN (0, 1)), CONSTRAINT `ck_items_access` CHECK((`access` IS NULL OR `access` IN ('open','closed')) AND ((`is_container` = 1) = (`access` IS NOT NULL))), CONSTRAINT `ck_items_is_full` CHECK(`is_full` IS NULL OR (`is_container` = 1 AND `is_full` IN (0, 1))), CONSTRAINT `ck_items_external_ids` CHECK(json_valid(`external_ids`) AND json_type(`external_ids`) = 'array'), CONSTRAINT `ck_items_revision` CHECK(`revision` >= 1));--> statement-breakpoint
INSERT INTO `items` SELECT i.`id`,i.`name`,t.`id`,i.`note`,i.`code`,i.`external_ids`,i.`quantity`,i.`lifecycle`,i.`lifecycle_changed_at`,i.`placement_kind`,i.`location_id`,i.`containing_item_id`,i.`previous_placement_kind`,i.`previous_location_id`,i.`previous_containing_item_id`,i.`is_container`,i.`access`,i.`is_full`,i.`legacy_type`,i.`location_text`,i.`room`,i.`item_id`,i.`brand`,i.`model`,i.`condition`,i.`in_use`,i.`deductible`,i.`purchase_date`,i.`warranty_expires`,i.`replacement_value`,i.`resale_value`,i.`purchase_transaction_id`,i.`purchase_transaction_uri`,i.`purchase_transaction_stale_at`,i.`purchased_from_id`,i.`purchased_from_name`,i.`purchase_price`,i.`owner_uri`,i.`owner_stale_at`,i.`source_ref`,i.`notion_id`,i.`last_edited_time`,i.`revision`,i.`seq`,i.`created_at`,i.`updated_at`,i.`deleted_at` FROM `items_legacy` i LEFT JOIN `item_types` t ON t.`revision` = 1 AND t.`key` = i.`type_key` COLLATE NOCASE;--> statement-breakpoint
