INSERT INTO `migration_0017_abort` SELECT 1 WHERE EXISTS (SELECT 1 FROM `items_legacy` i,json_each(i.`fields`) v LEFT JOIN `item_types` t ON t.`revision` = 1 AND t.`key` = i.`type_key` COLLATE NOCASE LEFT JOIN `item_type_fields` f ON f.`revision` = 1 AND f.`type_id` = t.`id` AND f.`key` = v.`key` COLLATE NOCASE WHERE NOT (i.`type_key` = 'bulb' AND v.`key` = 'Colour temperature') AND ((f.`kind` = 'short_text' AND (v.`type` <> 'text' OR length(v.`value`) NOT BETWEEN 1 AND 200)) OR (f.`kind` = 'boolean' AND v.`type` NOT IN ('true','false')) OR (f.`kind` = 'enum' AND (v.`type` <> 'text' OR NOT EXISTS (SELECT 1 FROM `field_enum_options` o WHERE o.`revision` = 1 AND o.`field_id` = f.`id` AND o.`label` = v.`value`))) OR (f.`kind` = 'measurement' AND (v.`type` <> 'object' OR json_type(v.`value`, '$.value') NOT IN ('integer','real') OR json_type(v.`value`, '$.unit') <> 'text' OR CASE f.`fixed_unit` WHEN 'm' THEN json_extract(v.`value`, '$.unit') NOT IN ('mm','cm','m') WHEN 'cm' THEN json_extract(v.`value`, '$.unit') NOT IN ('mm','cm','m') WHEN 'mm' THEN json_extract(v.`value`, '$.unit') NOT IN ('mm','cm','m') ELSE json_extract(v.`value`, '$.unit') <> f.`fixed_unit` END))));--> statement-breakpoint
